import fs from 'node:fs'; import p from 'node:fs/promises'; import h from './h.cjs';
const { fresh, ta, tree } = h;
const d = fresh('w-prom'); fs.writeFileSync(`${d}/a`, 'abcdef'); fs.mkdirSync(`${d}/t/s`, { recursive: true }); fs.writeFileSync(`${d}/t/s/f`, 'f'); fs.symlinkSync('s', `${d}/t/sl`);
await ta('copyFile', async () => { await p.copyFile(`${d}/a`, `${d}/b`); return fs.readFileSync(`${d}/b`, 'utf8'); });
await ta('copyFile EXCL', () => p.copyFile(`${d}/a`, `${d}/b`, fs.constants.COPYFILE_EXCL));
await ta('cp recursive', async () => { await p.cp(`${d}/t`, `${d}/t2`, { recursive: true }); return [tree(`${d}/t2`), fs.lstatSync(`${d}/t2/sl`).isSymbolicLink()]; });
await ta('cp no recursive dir', () => p.cp(`${d}/t`, `${d}/t3`));
await ta('cp into self', () => p.cp(`${d}/t`, `${d}/t/s/x`, { recursive: true }));
await ta('mkdtemp', async () => (await p.mkdtemp(`${d}/m-`)).length);
await ta('mkdtemp missing', () => p.mkdtemp(`${d}/no/m-`));
await ta('truncate', async () => { await p.truncate(`${d}/b`, 1); return fs.readFileSync(`${d}/b`, 'utf8'); });
await ta('truncate dir', () => p.truncate(d));
await ta('realpath', async () => (await p.realpath(`${d}/t/sl`)).endsWith(`${d}/t/s`));
await ta('realpath missing', () => p.realpath(`${d}/zz`));
await ta('opendir', async () => { const o = []; for await (const e of await p.opendir(`${d}/t`)) o.push(`${e.name}:${e.isSymbolicLink()}:${e.parentPath}`); return o.sort(); });
await ta('opendir recursive', async () => { const o = []; for await (const e of await p.opendir(`${d}/t`, { recursive: true })) o.push(`${e.parentPath}/${e.name}`); return o.sort(); });
await ta('rm dir', () => p.rm(`${d}/t2`));
await ta('rm missing', () => p.rm(`${d}/zz`));
await ta('rm missing force', () => p.rm(`${d}/zz`, { force: true }));
await ta('rm recursive', async () => { await p.rm(`${d}/t2`, { recursive: true }); return fs.existsSync(`${d}/t2`); });
await ta('rmdir non-empty', () => p.rmdir(`${d}/t`));
await ta('rmdir file', () => p.rmdir(`${d}/a`));
await ta('stat instanceof', async () => (await p.stat(`${d}/a`)) instanceof fs.Stats);
await ta('lstat symlink', async () => (await p.lstat(`${d}/t/sl`)).isSymbolicLink());
await ta('readdir recursive', async () => (await p.readdir(d, { recursive: true })).sort());
await ta('readdir recursive withFileTypes', async () => (await p.readdir(d, { recursive: true, withFileTypes: true })).map((e) => `${e.parentPath}|${e.name}`).sort());
await ta('chmod missing', () => p.chmod(`${d}/zz`, 0o600)); await ta('utimes missing', () => p.utimes(`${d}/zz`, 1, 1));
await ta('writeFile flag wx', () => p.writeFile(`${d}/a`, 'x', { flag: 'wx' }));
await ta('access missing', () => p.access(`${d}/zz`));
